insert into public.recetario_recetas as t (fuente, codigo, clase, nombre, descripcion, rendimiento, unidad, alergenos, procedimiento, componentes, propuesta) values
  ('RECETARIO COCINA', 'PR001', 'subreceta', 'Reducción de aceto balsámico', 'Subproceso de Sandwich de pera', 1391, 'ml', '{}'::text[], '1.1 Preparar área de trabajo: Limpiar, desinfectar superficies y utensilios. Sanitizar materias primas, ordenar según naturaleza y realizar mise and place.
1.2 En una olla disponer todos los ingredientes y llevar a ebullición hasta obtener textura de salsa. Rectificar punto de pimienta.', '[{"tipo":"ing","codigo":"OTR001","cantidad":1000,"unidad":"ml"},{"tipo":"ing","codigo":"INS047","cantidad":1000,"unidad":"g"},{"tipo":"ing","codigo":"OTR002","cantidad":5,"unidad":"g"}]'::jsonb, '{"pasos":["Preparar área de trabajo: Limpiar, desinfectar superficies y utensilios. Sanitizar materias primas, ordenar según naturaleza y realizar mise and place.","En una olla disponer todos los ingredientes y llevar a ebullición hasta obtener textura de salsa. Rectificar punto de pimienta."],"puntos":[{"tipo":"HIGIENE","texto":"Preparar área de trabajo: Limpiar, desinfectar superficies y utensilios. Sanitizar materias primas, ordenar según naturaleza y realizar mise and place.","de":"paso"},{"tipo":"CALIDAD","texto":"En una olla disponer todos los ingredientes y llevar a ebullición hasta obtener textura de salsa. Rectificar punto de pimienta.","de":"paso"}],"observaciones":[],"metodo":"Cocción","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"suma_entrada_g":2005,"suma_completa":true}'::jsonb),
  ('RECETARIO COCINA', 'PR002', 'subreceta', 'pera salteada', 'Subproceso de Sandwich de pera', 1117, 'g', '{}'::text[], '2.1 Laminar la pera de 0,03 centímetros de grosor, saltear en una sartén bien caliente con mantequilla, salpimentar y reservar.', '[{"tipo":"ing","codigo":"OTR003","cantidad":1117,"unidad":"g"},{"tipo":"ing","codigo":"OTR004","cantidad":265,"unidad":"g"},{"tipo":"ing","codigo":"INS004","cantidad":1,"unidad":"g"},{"tipo":"ing","codigo":"INS003","cantidad":1,"unidad":"g"}]'::jsonb, '{"pasos":["Laminar la pera de 0,03 centímetros de grosor, saltear en una sartén bien caliente con mantequilla, salpimentar y reservar."],"puntos":[],"observaciones":[],"metodo":"Salteado","alergenos_declarados":[],"alergenos_sugeridos":["Lácteos"],"suma_entrada_g":1384,"suma_completa":true}'::jsonb),
  ('RECETARIO COCINA', 'PR003', 'subreceta', 'pasta de higos', 'Subproceso de Sandwich de pera', 1117, 'g', '{}'::text[], '2.1 Cortar los higos en brunoisse, saltear con mantequilla y agregar azúcar y agua. Cocinar durante dos minutos. Reservar.', '[{"tipo":"ing","codigo":"OTR005","cantidad":1000,"unidad":"g"},{"tipo":"ing","codigo":"OTR004","cantidad":150,"unidad":"g"},{"tipo":"ing","codigo":"OTR006","cantidad":10,"unidad":"g"},{"tipo":"ing","codigo":"OTR007","cantidad":50,"unidad":"ml"}]'::jsonb, '{"pasos":["Cortar los higos en brunoisse, saltear con mantequilla y agregar azúcar y agua. Cocinar durante dos minutos. Reservar."],"puntos":[],"observaciones":[],"metodo":"Cocción y Salteado","alergenos_declarados":[],"alergenos_sugeridos":["Lácteos"],"suma_entrada_g":1210,"suma_completa":true}'::jsonb),
  ('RECETARIO COCINA', 'P001', 'plato', 'Sandwich de pera', null, 1, 'porciones', '{}'::text[], '2.1 En un bowl disponer el pre fermento previamente refrescado junto con los demás ingredientes. Amasar durante 1 minuto.
2.2 Cubrir el bowl con alusa plástica y dejar fermentar hasta que duplique su tamaño.
2.4 Realizar pliegues en formato de libro y justo en las uniones hacer pequeños pliegues para retener el gas de la fermentación. disponer en gastos rectangulares, disponer aceite de oliva en la superficie y espolvorear mix de hierbas. dejar fermentar hasta duplicar su volumen.
PUNTO CRÍTICO: Controlar temperatura de riesgo (mayor a 70ºC para preparaciones calientes y menor o igual a 3ºC en productos que requieran refrigeración). La masa debe de quedar sin grumos y bien hidratada.
OBSERVACIÓN: Conservar los lavash en un recipiente hermético hasta por 2 semanas.
OBSERVACIÓN: De cada salsa servir 25 gramos.', '[{"tipo":"ing","codigo":"OTR008","cantidad":1,"unidad":"und"},{"tipo":"ing","codigo":"OTR009","cantidad":42,"unidad":"g"},{"tipo":"ing","codigo":"OTR010","cantidad":42,"unidad":"g"},{"tipo":"sub","codigo":"PR001","cantidad":10,"unidad":"ml"},{"tipo":"ing","codigo":"OTR011","cantidad":12,"unidad":"g"},{"tipo":"sub","codigo":"PR003","cantidad":10,"unidad":"g"}]'::jsonb, '{"pasos":["En un bowl disponer el pre fermento previamente refrescado junto con los demás ingredientes. Amasar durante 1 minuto.","Cubrir el bowl con alusa plástica y dejar fermentar hasta que duplique su tamaño.","Realizar pliegues en formato de libro y justo en las uniones hacer pequeños pliegues para retener el gas de la fermentación. disponer en gastos rectangulares, disponer aceite de oliva en la superficie y espolvorear mix de hierbas. dejar fermentar hasta duplicar su volumen."],"puntos":[{"tipo":"TEMPERATURA","texto":"Controlar temperatura de riesgo (mayor a 70ºC para preparaciones calientes y menor o igual a 3ºC en productos que requieran refrigeración). La masa debe de quedar sin grumos y bien hidratada.","de":"escrito"}],"observaciones":["Conservar los lavash en un recipiente hermético hasta por 2 semanas.","De cada salsa servir 25 gramos."],"metodo":"Fermentación","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos","Lácteos"],"suma_entrada_g":116,"suma_completa":false}'::jsonb),
  ('RECETARIO COCINA', 'PR006', 'subreceta', 'Espuma de coco', 'Subproceso de Onda di mare', 4, 'porciones', '{}'::text[], '1.1 Preparar área de trabajo: Limpiar, desinfectar superficies y utensilios. Sanitizar materias primas, ordenar según naturaleza y realizar mise and place.
1.2 En un bowl disponer todos los ingredientes, mezclar y filtrar.
1.3 Disponer la mezcla en un sifón de una capacidad de 500 ml, procurar no llegar al limited de la capacidad. Una vez dispuesta la mezcla, cerrar e inyectar una cápsulas de óxido nitroso (N₂O).
1.4 Agitar con fuerza 10 veces, refrigerar mínimo 2 horas.
1.5 Para el almacenamiento al vacio, guardar en bolsas al vacio de 250 o 500 ml en congelación.', '[{"tipo":"ing","codigo":"OTR017","cantidad":200,"unidad":"ml"},{"tipo":"ing","codigo":"OTR018","cantidad":50,"unidad":"ml"},{"tipo":"ing","codigo":"INS004","cantidad":1,"unidad":"g"},{"tipo":"ing","codigo":"OTR019","cantidad":1,"unidad":"g"},{"tipo":"sub","codigo":"PR130","cantidad":5,"unidad":"ml"},{"tipo":"ing","codigo":"OTR021","cantidad":2,"unidad":"g"},{"tipo":"ing","codigo":"OTR194","cantidad":15,"unidad":"ml"},{"tipo":"ing","codigo":"OTR031","cantidad":2,"unidad":"g"}]'::jsonb, '{"pasos":["Preparar área de trabajo: Limpiar, desinfectar superficies y utensilios. Sanitizar materias primas, ordenar según naturaleza y realizar mise and place.","En un bowl disponer todos los ingredientes, mezclar y filtrar.","Disponer la mezcla en un sifón de una capacidad de 500 ml, procurar no llegar al limited de la capacidad. Una vez dispuesta la mezcla, cerrar e inyectar una cápsulas de óxido nitroso (N₂O).","Agitar con fuerza 10 veces, refrigerar mínimo 2 horas.","Para el almacenamiento al vacio, guardar en bolsas al vacio de 250 o 500 ml en congelación."],"puntos":[{"tipo":"HIGIENE","texto":"Preparar área de trabajo: Limpiar, desinfectar superficies y utensilios. Sanitizar materias primas, ordenar según naturaleza y realizar mise and place.","de":"paso"},{"tipo":"TIEMPO","texto":"Agitar con fuerza 10 veces, refrigerar mínimo 2 horas.","de":"paso"},{"tipo":"TEMPERATURA","texto":"Para el almacenamiento al vacio, guardar en bolsas al vacio de 250 o 500 ml en congelación.","de":"paso"}],"observaciones":[],"metodo":null,"alergenos_declarados":[],"alergenos_sugeridos":["Lácteos","Soya"],"suma_entrada_g":276,"suma_completa":true}'::jsonb),
  ('RECETARIO COCINA', 'PR007', 'subreceta', 'cubos de pasta', 'Subproceso de Onda di mare', 40, 'porciones', array['Sésamo']::text[], '2.1 Cocinar en una olla la pasta de arroz a partir de agua caliente junto con el peperoncino, sal y pimienta. Cocinar hasta que la pasta esté completamente blanda.
2.2 Filtrar el agua de cocción de la pasta y reservar. Licuar la pasta junto con la ralladura de jengibre y el aceite de ajonjolí hasta que se obtenga una mezcla lisa. Reservar.
2.3 Disponer la mezcla en una olla, incorporar el agar agar y llevar a ebullición durante 1 min, hasta que el agar agar realice el efecto de coagulación en la mezcla.
2.4 Disponer en moldes cuadrados de silicona, llevar a refrigeración hasta que estén completamente compactos.
2.5 Una vez compactos, cortar en parmetier y empacar en bolsas al vacio de 20 gr.
Importante al momento de licuar, medir la cantidad de agua, puede variar dependiendo de la humedad de la pasta. ', '[{"tipo":"ing","codigo":"OTR022","cantidad":500,"unidad":"g"},{"tipo":"ing","codigo":"OTR019","cantidad":1,"unidad":"g"},{"tipo":"ing","codigo":"OTR021","cantidad":1,"unidad":"g"},{"tipo":"ing","codigo":"INS004","cantidad":10,"unidad":"g"},{"tipo":"ing","codigo":"OTR023","cantidad":15,"unidad":"ml"},{"tipo":"ing","codigo":"OTR007","cantidad":350,"unidad":"ml"},{"tipo":"ing","codigo":"INS003","cantidad":1,"unidad":"g"},{"tipo":"ing","codigo":"OTR065","cantidad":5,"unidad":"g"}]'::jsonb, '{"pasos":["Cocinar en una olla la pasta de arroz a partir de agua caliente junto con el peperoncino, sal y pimienta. Cocinar hasta que la pasta esté completamente blanda.","Filtrar el agua de cocción de la pasta y reservar. Licuar la pasta junto con la ralladura de jengibre y el aceite de ajonjolí hasta que se obtenga una mezcla lisa. Reservar.","Disponer la mezcla en una olla, incorporar el agar agar y llevar a ebullición durante 1 min, hasta que el agar agar realice el efecto de coagulación en la mezcla.","Disponer en moldes cuadrados de silicona, llevar a refrigeración hasta que estén completamente compactos.","Una vez compactos, cortar en parmetier y empacar en bolsas al vacio de 20 gr.","Importante al momento de licuar, medir la cantidad de agua, puede variar dependiendo de la humedad de la pasta."],"puntos":[{"tipo":"TIEMPO","texto":"Disponer la mezcla en una olla, incorporar el agar agar y llevar a ebullición durante 1 min, hasta que el agar agar realice el efecto de coagulación en la mezcla.","de":"paso"},{"tipo":"TEMPERATURA","texto":"Disponer en moldes cuadrados de silicona, llevar a refrigeración hasta que estén completamente compactos.","de":"paso"},{"tipo":"TEMPERATURA","texto":"Una vez compactos, cortar en parmetier y empacar en bolsas al vacio de 20 gr.","de":"paso"}],"observaciones":[],"metodo":"Procesado y Cocción","alergenos_declarados":["Sésamo"],"ale