  ('RECETARIO COCINA', 'PR009', 'subreceta', 'Pasta de ajillo', 'Subproceso de Onda di mare', 15, 'porciones', '{}'::text[], '1.1 Cortar las puntas de  la cabeza de los ajos, y disponer en una sarten de hierro fundido con los demás ingredietes, y llevar al horno a 180 °C por 15 a 20 min. o hasta que los dientes de ajo se vuelvan blanditos.', '[{"tipo":"ing","codigo":"OTR039","cantidad":315,"unidad":"und"},{"tipo":"ing","codigo":"INS004","cantidad":6,"unidad":"g"},{"tipo":"ing","codigo":"INS046","cantidad":6,"unidad":"ml"}]'::jsonb, '{"pasos":["Cortar las puntas de la cabeza de los ajos, y disponer en una sarten de hierro fundido con los demás ingredietes, y llevar al horno a 180 °C por 15 a 20 min. o hasta que los dientes de ajo se vuelvan blanditos."],"puntos":[{"tipo":"TEMPERATURA","texto":"Cortar las puntas de la cabeza de los ajos, y disponer en una sarten de hierro fundido con los demás ingredietes, y llevar al horno a 180 °C por 15 a 20 min. o hasta que los dientes de ajo se vuelvan blanditos.","de":"paso"}],"observaciones":[],"metodo":"Horneado","alergenos_declarados":[],"alergenos_sugeridos":[],"suma_entrada_g":12,"suma_completa":false}'::jsonb),
