  ('RECETARIO COCINA', 'PR022', 'subreceta', 'Mariscada', 'Subproceso de Mariscada', 128, 'g', '{}'::text[], '3.1 Disponer todos los ingredientes en una bolsa al vacío, sellar y llevar a congelación', '[{"tipo":"ing","codigo":"OTR061","cantidad":3,"unidad":"g"},{"tipo":"sub","codigo":"PR009","cantidad":1,"unidad":"porciones"},{"tipo":"ing","codigo":"OTR063","cantidad":3,"unidad":"und"},{"tipo":"ing","codigo":"INS032","cantidad":6,"unidad":"g"},{"tipo":"ing","codigo":"OTR062","cantidad":3,"unidad":"g"}]'::jsonb, '{"pasos":["Disponer todos los ingredientes en una bolsa al vacío, sellar y llevar a congelación"],"puntos":[{"tipo":"TEMPERATURA","texto":"Disponer todos los ingredientes en una bolsa al vacío, sellar y llevar a congelación","de":"paso"}],"observaciones":[],"metodo":null,"alergenos_declarados":[],"alergenos_sugeridos":["Moluscos","Crustáceos"],"suma_entrada_g":12,"suma_completa":false}'::jsonb),
  ('RECETARIO COCINA', 'PR023', 'subreceta', 'Gel de limón', 'Subproceso de Mariscada', 20, 'porciones', '{}'::text[], '4.1 Disponer todos los ingredientes en una olla, revolver y llevar a ebullición hasta que el agar agar realice su acción coagulante .
