  ('RECETARIO COCINA', 'P011', 'plato', 'BROCHETAS', null, 1, 'porciones', array['Gluten', 'Huevo']::text[], '3.1 Llevar las brochetas con un cubito de mantequilla en una bandeja al horno a 200°C por 10 a 12 min.
