  ('RECETARIO COCINA', 'P030', 'plato', 'EXPERIENCIA DE ARANCINIS', null, 20, 'porciones', array['Gluten', 'Huevo', 'Lácteos']::text[], '1.1 Con la mezcla de arroz arancinis, realizar esferas de 40 gr cada una, disponer en una lata, congelar y almacenar en paquetes de 5 un
