  ('RECETARIO COCINA', 'PR068', 'subreceta', 'Arancini de Vegetales', 'Subproceso de Arancinis de viaggio', 20, 'porciones', array['Lácteos']::text[], '4.1 Cortar los vegetales en brunoise, Reservar.
