  ('RECETARIO COCINA', 'P037', 'plato', 'PASTA RA', 'Pasta fresca de huevo acompañada de salsa carbonara, terminada con queso parmesano y pan tostado.', 1, 'porciones', array['Gluten', 'Lácteos', 'Huevo']::text[], '5.1 Cortar la tocineta en brunoise, saltear y reservar.
